function filtered(key){var rows=(N.data[key]||[]).slice(),s=N.search.toLowerCase().trim();if(N.filters.status!=='all')rows=rows.filter(function(x){return String(x.status||x.lifecycle_status||'').toLowerCase()===N.filters.status;});if(N.filters.type!=='all')rows=rows.filter(function(x){return String(x.type||x.survey_type||x.measurement_type||'').toLowerCase()===N.filters.type;});if(N.filters.period&&['programmes','plans','surveys','measurements','assessments','controls','reports'].includes(key))rows=rows.filter(function(x){var d=x.survey_date||x.measurement_date||x.assessment_date||x.start_date||x.created_at||'';return !d||String(d).slice(0,7)===N.filters.period;});if(s)rows=rows.filter(function(x){return Object.values(x).some(function(v){return typeof v==='string'&&v.toLowerCase().includes(s);});});return rows;}
