window.noiseCloseDrawer=function(force){if(N.drawerDirty&&!force&&!confirm('Discard unsaved changes?'))return;document.getElementById('noise-drawer')?.classList.remove('open');};
window.noiseOpenForm=function(kind,existing){var f=FORMS[kind];if(!f)return toast2('This action is not configured',false);var row=existing||{},body='<div class="noise-note">Save Draft preserves work. Approval/publication validates dependencies and creates immutable versions where required.</div><div class="noise-form-grid" style="margin-top:13px">'+f.fields.map(function(x){return field(x[0],'noise-f-'+x[1],x[2],x[3],row[x[1]],x[4]);}).join('')+'</div>';drawer((row.id?'Edit ':'Create ')+f.title,body,btn('Cancel','noiseCloseDrawer()')+btn(row.id?'Save changes':'Save Draft',"noiseSaveForm('"+kind+"','"+h(row.id||'')+"')",'primary','ti-device-floppy'));document.querySelectorAll('#noise-drawer input,#noise-drawer select,#noise-drawer textarea').forEach(function(e){e.oninput=e.onchange=function(){N.drawerDirty=true;};});};
function serialise(kind){var f=FORMS[kind],o={company_id:cid(),updated_at:new Date().toISOString()};f.fields.forEach(function(x){var v=value('noise-f-'+x[1]);if(x[2]==='number')v=v===''?null:Number(v);if(x[1]==='restriction_flag')v=v==='true';if(['payload','test_cases','parameters_json','bands_json','test_cases_json'].includes(x[1])){try{v=v?JSON.parse(v):(x[1].includes('cases')||x[1]==='bands_json'?[]:{});}catch(e){throw new Error(x[0]+' must contain valid JSON');}}o[x[1]]=v||(['effective_to','next_due_date','calibration_date','calibration_due_date','last_surveillance_date','next_surveillance_date','issued_at'].includes(x[1])?null:v);});return o;}
async function persist(tableName,row,id){var options=id?{m:'PATCH',p:'return=representation',b:row}:{m:'POST',p:'return=representation',b:Object.assign({created_by:pid(),created_at:new Date().toISOString()},row)};var url='/'+tableName+(id?'?id=eq.'+encodeURIComponent(id):'');var out=await api(url,options);return out?.[0]||Object.assign({id:id||('local-'+Date.now())},row);}
async function audit(entity,id,action,before,after,reason){try{await api('/noise_mgmt_audit_events',{m:'POST',p:'return=minimal',b:{company_id:cid(),entity_type:entity,entity_id:String(id),action:action,before_json:before||null,after_json:after||null,reason:reason||null,performed_by:pid(),performed_by_name:pname2()}});}catch(_){}}
window.noiseSaveForm=async function(kind,id){var f=FORMS[kind],row;try{row=serialise(kind);}catch(e){return toast2(e.message,false);}var recordCode=kind==='instrument'?row.asset_code:row.code;if(!recordCode&&!['health'].includes(kind))return toast2('A unique code is required',false);if(!row.name&&['source','task','seg','programme','map','protector','report','profile','config'].includes(kind))return toast2('Name is required',false);if(kind==='assessment'){var l=Number(row.source_level),t=Number(row.duration_hours),ref=8;if(!isFinite(l)||!isFinite(t)||t<=0)return toast2('Representative level and positive duration are required',false);row.result_value=Number((l+10*Math.log10(t/ref)).toFixed(2));row.result_unit='dB(A)';row.calculation_method='LEX_REF_DURATION';row.calculation_snapshot={source_level:l,duration_hours:t,reference_duration_hours:ref,formula:'L + 10 log10(T/Tref)',profile:row.profile_name};row.classification='profile_pending';}
try{var before=id?(N.data[f.table]||[]).find(function(x){return String(x.id)===String(id);}):null,saved=await persist(TABLES[f.table],row,id);if(before)Object.assign(before,saved);else N.data[f.table].unshift(saved);await audit(f.table,saved.id,id?'updated':'created',before,saved,row.change_reason);N.drawerDirty=false;noiseCloseDrawer(true);render();toast2(f.title+' saved');}catch(e){toast2('Not saved: '+(e.message||'Database upgrade or permission required'),false);}};
window.noiseOpenRecord=function(key,id){var row=(N.data[key]||[]).find(function(x){return String(x.id)===String(id);});if(!row)return;var formKind=Object.keys(FORMS).find(function(k){return FORMS[k].table===key;}),hidden=['company_id','before_json','after_json'],body='<div class="noise-list">'+Object.keys(row).filter(function(k){return !hidden.includes(k)&&row[k]!==null&&row[k]!=='';}).map(function(k){var v=typeof row[k]==='object'?JSON.stringify(row[k]):row[k];return '<div class="noise-list-row"><div><b>'+h(label(k))+'</b></div><span style="max-width:62%;text-align:right;overflow-wrap:anywhere">'+h(v)+'</span></div>';}).join('')+'</div><div class="noise-note" style="margin-top:12px">Material changes, exclusions, approvals and supersessions are recorded in the audit trail.</div>';var foot=btn('Close','noiseCloseDrawer()');if(canManage()&&formKind&&!['approved','issued','published','superseded','archived'].includes(row.status))foot+=btn('Edit',"noiseEditRecord('"+formKind+"','"+key+"','"+h(id)+"')",'primary','ti-edit');drawer(formKind?FORMS[formKind].title:'Noise record',body,foot);};
window.noiseEditRecord=function(formKind,key,id){var row=(N.data[key]||[]).find(function(x){return String(x.id)===String(id);});if(!row)return;noiseCloseDrawer(true);noiseOpenForm(formKind,row);};
function formSubset(kind,names,row){var f=FORMS[kind];return '<div class="noise-form-grid">'+names.map(function(name){var x=f.fields.find(function(y){return y[1]===name;});return x?field(x[0],'noise-f-'+x[1],x[2],x[3],row?.[x[1]],x[4]):'';}).join('')+'</div>';}
window.noiseOpenMapWizard=function(existing){var row=existing||{},steps=[['1','Identity & scope'],['2','Base plan & scale'],['3','Measurement data'],['4','Rules & layers'],['5','Review & quality'],['6','Publication']];var body='<div class="noise-stepper">'+steps.map(function(s){return '<div><b>'+s[0]+'</b><span>'+s[1]+'</span></div>';}).join('')+'</div><section class="noise-wizard-section"><h3>1. Identity & scope</h3>'+formSubset('map',['code','name','map_type','site','survey_code','data_period','owner_name','reviewer_name','descriptor','profile_name','operating_condition','confidentiality'],row)+'</section><section class="noise-wizard-section"><h3>2. Base plan & scale</h3><div class="noise-note">The original plan, filename, checksum, uploader and revision remain traceable. Scale is calibrated from two plan points and a known distance.</div>'+formSubset('map',['plan_filename','scale_distance','scale_unit','orientation_degrees','coordinate_mode'],row)+'</section><section class="noise-wizard-section"><h3>3. Measurement data</h3><div class="noise-note">After saving the draft, use the map workspace to select accepted compatible measurements. Ineligible records remain visible with reasons.</div></section><section class="noise-wizard-section"><h3>4. Map rules & layers</h3>'+formSubset('map',['interpolation_method'],row)+'<div class="noise-note warn" style="margin-top:10px">Point-only is always available. Derived contours require a published method, compatible data, a supported boundary and a passed density/distribution gate.</div></section><section class="noise-wizard-section"><h3>5. Review & quality</h3>'+formSubset('map',['quality_status','limitations','review_due_date'],row)+'</section><section class="noise-wizard-section"><h3>6. Publication</h3>'+formSubset('map',['status'],row)+'<div class="noise-note privacy" style="margin-top:10px">Publication freezes source versions, plan, scale, profile, settings, legend, reviewer, limitations and checksum. Published maps are changed only through a new version.</div></section>';drawer(row.id?'Revise Noise Map':'Create Noise Map',body,btn('Cancel','noiseCloseDrawer()')+btn(row.id?'Save revised draft':'Save Draft',"noiseSaveForm('map','"+h(row.id||'')+"')",'primary','ti-device-floppy'));document.querySelectorAll('#noise-drawer input,#noise-drawer select,#noise-drawer textarea').forEach(function(e){e.oninput=e.onchange=function(){N.drawerDirty=true;};});};
window.noiseOpenMapWorkspace=function(id){var map=(N.data.maps||[]).find(function(x){return String(x.id)===String(id);});if(!map)return;var pts=(N.data.mapPoints||[]).filter(function(x){return String(x.map_id)===String(id);}),layers=(N.data.mapLayers||[]).filter(function(x){return String(x.map_id)===String(id);}),surfaces=(N.data.mapSurfaces||[]).filter(function(x){return String(x.map_id)===String(id);}),checks=[['Base plan and scale',!!map.plan_filename&&Number(map.scale_distance)>0],['Source traceability',pts.every(function(x){return !!x.measurement_id;})],['Descriptor and profile',!!map.descriptor&&!!map.profile_name],['Placed source points',pts.length>0&&pts.every(function(x){return x.placement_status==='placed'||x.status==='excluded';})],['Contour quality gate',map.interpolation_method==='point_only'||surfaces.some(function(x){return x.status==='validated';})],['Limitation statement',!!map.limitations]];var body='<div class="noise-map-workspace"><div class="noise-map-toolbar">'+btn('Revise',"noiseCloseDrawer(true);noiseOpenMapWizard(N.data.maps.find(function(x){return String(x.id)==='"+h(id)+"';}))",'','ti-edit')+btn('Link measurements',"noiseMapLinkMeasurements('"+h(id)+"')",'','ti-link')+btn('Add layer',"noiseMapAddLayer('"+h(id)+"')",'','ti-layers-linked')+btn('Validate',"noiseMapValidate('"+h(id)+"')",'primary','ti-shield-check')+'</div><div class="noise-map-canvas"><div><i class="ti ti-map-2"></i><b>'+h(map.plan_filename||'Base plan not attached')+'</b><span>'+h(map.coordinate_mode||'plan_xy')+' · '+(map.scale_distance?h(map.scale_distance+' '+map.scale_unit):'Scale not calibrated')+'</span></div>'+pts.map(function(p,i){return '<button style="left:'+(p.plan_x||15+i*11)+'%;top:'+(p.plan_y||30+(i%3)*18)+'%" title="'+h(p.label||'Linked measurement')+'">'+(i+1)+'</button>';}).join('')+'</div><div class="noise-grid two" style="margin-top:12px"><section class="noise-card"><div class="noise-card-title">Measurement points <span>'+pts.length+'</span></div>'+(pts.length?'<div class="noise-list">'+pts.map(function(p){return '<div class="noise-list-row"><div><b>'+h(p.label||p.measurement_id)+'</b><small>'+h(label(p.placement_status))+' · source v'+h(p.measurement_version||1)+'</small></div>'+badge(p.status)+'</div>';}).join('')+'</div>':empty('No linked measurements','Link accepted compatible source records; values cannot be typed into the map.'))+'</section><section class="noise-card"><div class="noise-card-title">Layers & surfaces</div><div class="noise-list">'+layers.map(function(l){return '<div class="noise-list-row"><div><b>'+h(l.name)+'</b><small>'+h(label(l.layer_type))+'</small></div>'+badge(l.status)+'</div>';}).join('')+(surfaces.map(function(s){return '<div class="noise-list-row"><div><b>Derived surface</b><small>'+h(s.method_code)+' · '+h(s.method_version)+'</small></div>'+badge(s.status)+'</div>';}).join('')||'<div class="noise-list-row"><div><b>Point-only map</b><small>No derived surface published</small></div>'+badge('available')+'</div>')+'</div></section></div><section class="noise-card" style="margin-top:12px"><div class="noise-card-title">Publication quality gate</div><div class="noise-list">'+checks.map(function(c){return '<div class="noise-list-row"><div><b>'+h(c[0])+'</b></div>'+badge(c[1]?'passed':'blocked')+'</div>';}).join('')+'</div></section></div>';drawer((map.code||'Map')+' · v'+(map.version_no||1),body,btn('Close','noiseCloseDrawer()')+btn('Compare versions','noiseMapCompare()','','ti-versions'));};
window.noiseMapLinkMeasurements=function(mapId){var linked=(N.data.mapPoints||[]).filter(function(x){return String(x.map_id)===String(mapId);}).map(function(x){return String(x.measurement_id);}),eligible=(N.data.measurements||[]).filter(function(x){return ['accepted','approved'].includes(x.status)&&!linked.includes(String(x.id));});var body=eligible.length?'<div class="noise-list">'+eligible.map(function(x){return '<div class="noise-list-row"><div><b>'+h(x.code||x.id)+'</b><small>'+h(x.descriptor||'')+' · '+h(x.raw_value)+' '+h(x.unit||'')+' · '+h(x.subject_name||x.location||'')+'</small></div>'+btn('Link',"noiseAddMapPoint('"+h(mapId)+"','"+h(x.id)+"')",'compact','ti-link')+'</div>';}).join('')+'</div>':empty('No eligible measurements','Only accepted compatible records may be linked. Review descriptor, quality, date, scope and duplicate-source reasons.');drawer('Add measurement points',body,btn('Close','noiseCloseDrawer()'));};
window.noiseAddMapPoint=async function(mapId,measurementId){try{var m=(N.data.measurements||[]).find(function(x){return String(x.id)===String(measurementId);}),row=await persist(TABLES.mapPoints,{company_id:cid(),map_id:mapId,measurement_id:measurementId,measurement_version:m?.version_no||1,label:m?.code||m?.subject_name||'Measurement',placement_status:'unplaced',status:'included'},'');N.data.mapPoints.unshift(row);noiseCloseDrawer(true);noiseOpenMapWorkspace(mapId);toast2('Measurement linked and queued for placement');}catch(e){toast2('Measurement was not linked: '+(e.message||'Permission or schema error'),false);}};
window.noiseMapAddLayer=function(mapId){var body='<div class="noise-form-grid">'+field('Layer type','noise-layer-type','select',[['noise_source','Noise sources'],['hearing_zone','Hearing-protection zone'],['engineering_control','Engineering controls'],['access_route','Access route / occupancy'],['annotation','Annotation'],['external','External / reference']],'noise_source')+field('Layer name','noise-layer-name','text',null,'')+field('Source / approval reference','noise-layer-source','text',null,'','full')+'</div>';drawer('Add controlled map layer',body,btn('Cancel','noiseCloseDrawer()')+btn('Save layer',"noiseSaveMapLayer('"+h(mapId)+"')",'primary','ti-device-floppy'));};
window.noiseSaveMapLayer=async function(mapId){if(!value('noise-layer-name'))return toast2('Layer name is required',false);try{var row=await persist(TABLES.mapLayers,{company_id:cid(),map_id:mapId,layer_type:value('noise-layer-type'),name:value('noise-layer-name'),source_entity_id:value('noise-layer-source'),status:'draft',geometry_json:{},style_json:{}},'');N.data.mapLayers.unshift(row);noiseCloseDrawer(true);noiseOpenMapWorkspace(mapId);toast2('Controlled layer saved');}catch(e){toast2('Layer not saved: '+(e.message||'Permission or schema error'),false);}};
window.noiseMapValidate=function(mapId){var m=(N.data.maps||[]).find(function(x){return String(x.id)===String(mapId);}),pts=(N.data.mapPoints||[]).filter(function(x){return String(x.map_id)===String(mapId)&&x.status!=='excluded';}),blocking=[];if(!m?.plan_filename||!(Number(m.scale_distance)>0))blocking.push('Base plan and calibrated scale are required.');if(!m?.descriptor||!m?.profile_name)blocking.push('Descriptor and published profile are required.');if(!pts.length)blocking.push('At least one source-linked measurement is required.');if(pts.some(function(x){return !x.measurement_id;}))blocking.push('Every technical value must resolve to a source measurement.');if(m?.interpolation_method!=='point_only'&&pts.length<3)blocking.push('Contour quality gate failed; retain a point-only map or add supported coverage.');drawer('Noise Map quality validation','<div class="noise-note '+(blocking.length?'warn':'')+'"><b>'+(blocking.length?blocking.length+' blocking check(s)':'All current blocking checks passed')+'</b><br>'+(blocking.length?blocking.map(h).join('<br>'):'Independent reviewer approval and publication reason remain required.')+'</div><div class="noise-list" style="margin-top:12px"><div class="noise-list-row"><b>Measured points distinguishable from derived surfaces</b>'+badge('required')+'</div><div class="noise-list-row"><b>Published artefacts immutable</b>'+badge('required')+'</div><div class="noise-list-row"><b>Limitations included on screen and export</b>'+badge(m?.limitations?'passed':'blocked')+'</div></div>',btn('Close','noiseCloseDrawer()'));};
window.noiseMapCompare=function(){drawer('Map version comparison','<div class="noise-note">Select two stored map versions to compare plan, points, measurement values, profile, layers, method, boundary, limitations and conclusion. No second version is available in this workspace yet.</div>',btn('Close','noiseCloseDrawer()'));};
window.noiseConfigGroup=function(group){N.configGroup=group;render();document.querySelector('.main')?.scrollTo({top:0,behavior:'smooth'});};
