window.noiseTestConfig=function(){var rows=(N.data.config||[]).filter(function(x){return N.configGroup==='Overview'||x.workspace===N.configGroup;}),tests=rows.reduce(function(n,x){return n+(Array.isArray(x.test_cases)?x.test_cases.length:0);},0);drawer('Configuration test workspace','<div class="noise-grid two">'+metric('ti-database','Records in scope',rows.length,'No production values changed')+metric('ti-flask','Stored test cases',tests,'Reproducible expected outcomes','blue')+'</div><div class="noise-note" style="margin-top:12px">Tests run against Draft configuration and do not change active calculations, maps, workflows, classifications or notifications. Results require human review before publication.</div>',btn('Close','noiseCloseDrawer()'));};
